        [ 3.15790346e-02,  1.42522958e-02,  3.00694189e-01, -1.09355217e-01, -1.22301936e-01, -9.75728097e-02,  4.42117881e-03,  7.82637808e-02,  1.07313130e-01, -8.99434667e-02,  5.39206818e-03, -6.31146157e-02,  9.29421851e-02,  4.07787097e-02, -2.03724205e-01,  1.03756777e-02],
