        [ 1.05202802e-01, -1.24151864e-01, -1.22301936e-01, -8.82691109e-02,  2.68360817e-01,  2.26223064e-01, -8.12731623e-03, -8.51244740e-02,  4.40573013e-02,  4.11066307e-02,  3.23120194e-02,  8.15563030e-02, -1.01633017e-01, -2.05090504e-01, -6.81236144e-02,  4.00289887e-03],
