        [ 2.95624830e-02, -7.57293841e-02, -6.31146157e-02, -4.84796460e-02,  8.15563030e-02,  2.59113072e-02, -2.46950151e-02,  3.10707023e-02,  9.64049744e-03,  8.18018133e-02,  4.73363758e-02,  8.80981582e-02, -9.32860360e-02, -8.53779339e-02, -5.66689645e-02,  5.23739550e-02],
        [ 8.67987075e-04,  1.35325080e-01,  9.29421851e-02, -4.49782452e-02, -1.01633017e-01, -4.92135424e-02, -4.24992752e-02, -7.26043405e-03, -2.14764399e-02, -1.83082264e-01, -1.84424147e-02, -9.32860360e-02,  4.83833898e-01, -1.38007906e-02, -1.26720224e-01, -1.05764659e-02],
